#include <stdio.h>

#define SHOW(expr) printf("%s = %d\n", #expr, (expr))

int main(void) {
    int a, b;
    while (scanf("%d %d", &a, &b) == 2) {
        SHOW(a + b);
        SHOW(a * b - 1);
        SHOW((a > b) ? a : b);
        SHOW(a % 3);
        SHOW(a   ==   b);
        puts("---");
    }
    return 0;
}

